fields.InputDefinition:
{
  "goal": "Navigate to Data Explorer and open the 'People' entity (type 'People' in the LEFT sidebar 'Search record types...' box and click the exact 'People' match, or navigate to http://localhost:4200/app/data-explorer/Data?entity=MJ_BizApps_Common:%20People) to see the records grid. Type 'Rodriguez' in the grid's filter box ('Filter records...'), click the row for Elena Rodriguez, then click 'Open Full Record'. Verify that the detail form displays with populated fields such as First Name, Last Name, Title, or Email.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The People detail form for Elena Rodriguez is displayed with populated fields",
    "Fields such as First Name, Last Name, Title (Head Cheesemaker) or Email are visible and have values"
  ]
}
